          if (lower.includes('.طرد')) { if (!isGroup) { await r('⚠️ الطرد يخدم في القروب بس'); continue; } let targetJid = null; let numsForKick = getTargets(text, ctx, quotedParticipant); let resKick = await resolveTargetsByUsername(text, numsForKick); numsForKick = resKick.nums; if (quotedParticipant) targetJid = quotedParticipant; else if (ctx && ctx.mentionedJid && ctx.mentionedJid.length) targetJid = ctx.mentionedJid[0]; else if (numsForKick.length) targetJid = numsForKick[0] + '@s.whatsapp.net'; if (!targetJid) { await r('⚠️ رد على رسالة الشخص ولا تاقيه ولا ابعث رقمه ولا يوزره'); continue; } let targetNum = getNum(targetJid); if (isWhite(targetNum)) { await r('🤍 تعذر، لأنه في القائمة البيضاء'); continue; } let candidates = [targetJid]; if (targetJid.includes('@s.whatsapp.net')) candidates.push(targetNum + '@lid'); if (targetJid.includes('@lid')) candidates.push(targetNum + '@s.whatsapp.net'); try { let meta = await sock.groupMetadata(from); let p = meta.participants.find(x => getNum(x.id) === targetNum || (x.phoneNumber && getNum(x.phoneNumber) === targetNum) || (lidMap[targetNum] && x.phoneNumber && getNum(x.phoneNumber) === lidMap[targetNum])); if (p) candidates.unshift(p.id); } catch(e) {} let ok = false; let tried = new Set(); for (let cand of candidates) { if (tried.has(cand)) continue; tried.add(cand); try { ok = await kickAndRename(from, cand, 'طرد يدوي'); } catch(e) {} if (ok) break; } if (ok) { if (blackList.indexOf(targetNum) === -1) { blackList.push(targetNum); saveLists(); } notifyOwner('🚨 طردت +' + targetNum + ' من قروب ' + from + '\nالسبب: طرد يدوي بأمر المالك'); } else { await r('❌ فشل الطرد - تأكد ان البوت أدمن'); } continue; }
          if (lower.includes('.فك حظر') || lower.includes('.الغاء حظر') || lower.includes('.الغاء بلاك')) { let nums = getTargets(text, ctx, quotedParticipant); let resU = await resolveTargetsByUsername(text, nums); nums = resU.nums; let expanded = await expandTargets(nums, from); if (expanded.length) { for (let n of expanded) blackList = blackList.filter((x) => x !== n); saveLists(); await r('✅ فكيت الحظر العام على ' + expanded.length + ' رقم'); } else { await r('⚠️ رد على رسالته ولا تاقيه ولا ابعث رقمه ولا يوزره'); } continue; }
          if (lower.includes('.الغاء ابيض')) { let nums = getTargets(text, ctx, quotedParticipant); let resU = await resolveTargetsByUsername(text, nums); nums = resU.nums; let expanded = await expandTargets(nums, from); for (let n of expanded) whiteList = whiteList.filter((x) => x !== n); saveLists(); await r('✅ نحيت ' + expanded.length + ' رقم من البيضاء'); continue; }
          if (lower.includes('.حظر الكل') || lower.includes('.حظر جماعي') || lower.includes('.حظر') || lower.includes('.اضف بلاك')) { let nums = getTargets(text, ctx, quotedParticipant); let resU = await resolveTargetsByUsername(text, nums); nums = resU.nums; let expanded = await expandTargets(nums, from); let inWhite = expanded.filter((n) => isWhite(n)); let toBan = expanded.filter((n) => !isWhite(n)); if (inWhite.length && toBan.length === 0) { await r('⛔ تعذر، لأنه في القائمة البيضاء'); continue; } if (toBan.length) { for (let n of toBan) { if (blackList.indexOf(n) === -1) blackList.push(n); } saveLists(); await r('🚫 حظرت ' + toBan.length + ' رقم في البلاك العام'); let k = await kickBlacklistedFromAllGroups(); if (k > 0) await r('✅ طردت ' + k + ' واحد من كل القروبات'); else await r('✅ ما لقيتاش داخل في أي قروب توا، لكن لو حاول يخش حينطرد طول'); if (toBan.length >= 10) await notifyOwner('🚨 حظر جماعي عام: ' + toBan.length + ' رقم'); } else { if (resU.userMentions.length) { await r('⚠️ ما لقيتش اليوزر ' + resU.userMentions.join(', ') + ' في أي قروب مع البوت\nجرب: خش للقروب اللي فيه، ورد على رسالته واكتب .حظر'); } else { await r('⚠️ رد على رسالته ولا تاقيه ولا ابعث رقمه ولا يوزره + .حظر'); } } continue; }
          if (lower.includes('.ابيض')) { let nums = getTargets(text, ctx, quotedParticipant); let resU = await resolveTargetsByUsername(text, nums); nums = resU.nums; let expanded = await expandTargets(nums, from); if (expanded.length) { let inBlack = expanded.filter((n) => isBlack(n)); let toAdd = expanded.filter((n) => !isBlack(n)); if (inBlack.length) { await r('⛔ تعذر، لأنه في القائمة السوداء'); continue; } for (let n of toAdd) { if (whiteList.indexOf(n) === -1) whiteList.push(n); } saveLists(); await r('✅ ضفت ' + toAdd.length + ' رقم للبيضاء من قروب ' + from); } else { await r('⚠️ رد على رسالته ولا تاقيه ولا ابعث رقمه ولا يوزره + .ابيض'); } continue; }
