        if (isBlackSender) { if (!canActOnUser('black-'+senderNum)) continue; tripleStrike(from, m, sender); notifyOwner('🚨 طردت +' + senderNum + ' من قروب ' + from + '\nالسبب: في البلاك العام\nشن بعت: ' + getMsgPreview(m, text)); continue; }
        if (isForward) { if (!canActOnUser('fwd-'+senderNum)) continue; tripleStrikeLock5(from, m, sender, 'اعادة توجيه'); if (!forwardedLocked[from]) { forwardedLocked[from] = true; notifyOwner('🚨 فوروارد من +' + senderNum + ' في قروب ' + from + ' - سكرت 5 دقايق + طرد\nشن بعت: ' + getMsgPreview(m, text)); setTimeout(()=>{ forwardedLocked[from] = false; }, 3*60*1000); } if (blackList.indexOf(senderNum) === -1) { blackList.push(senderNum); saveLists(); } continue; }
        if (hasLink(text)) { if (!canActOnUser('link-'+senderNum)) continue; if (lockLinks) { tripleStrikeLock5(from, m, sender, 'رابط - الروابط مقفولة'); notifyOwner('🚨 طردت +' + senderNum + ' من قروب ' + from + '\nالسبب: الروابط مقفولة\nشن بعت: ' + getMsgPreview(m, text)); continue; } fastDelete(from, m.key); linkCount[senderNum] = (linkCount[senderNum] || 0) + 1; if (linkCount[senderNum] >= 2) { fastKick(from, sender); lockGroup5Min(from, 'رابط مكرر', senderNum); notifyOwner('🚨 طردت +' + senderNum + ' من قروب ' + from + '\nالسبب: رابط مكرر - قفل 5 دقايق\nشن بعت: ' + getMsgPreview(m, text)); linkCount[senderNum] = 0; } else { lockGroup5Min(from, 'ارسال رابط', senderNum); notifyOwner('🔒 سكرت القروب ' + from + ' 5 دقايق\nالسبب: +' + senderNum + ' بعت رابط\nشن بعت: ' + getMsgPreview(m, text)); } continue; }
